// src/bootstrap/controller.ts
var ROUTER_OPTIONS = ["get", "post", "put", "patch", "delete"];
var Controller = class {
  constructor(name) {
    this.name = name;
    this.path = `/${name}`;
  }
  /** Return all prototype method names implemented on this instance. */
  listAllMethods() {
    const proto = Object.getPrototypeOf(this);
    const names = Object.getOwnPropertyNames(proto);
    return names.filter((n) => {
      if (n === "constructor") return false;
      const val = proto[n];
      return typeof val === "function";
    });
  }
  /** Return only HTTP method names that this controller actually implements. */
  list() {
    const implemented = new Set(this.listAllMethods());
    return ROUTER_OPTIONS.filter((m) => implemented.has(m));
  }
  initializeRoutes(router) {
    const list = this.list();
    const toUpper = (m) => m.toUpperCase();
    list.forEach((routeName) => {
      const maybe = this[routeName];
      if (typeof maybe !== "function") return;
      const func = maybe.bind(this);
      const pathMap = {
        func,
        method: toUpper(routeName)
      };
      router.add(this.name, pathMap);
    });
  }
};

// src/bootstrap/db.ts
import { DynamoDBClient } from "@aws-sdk/client-dynamodb";
import { DynamoDBDocumentClient } from "@aws-sdk/lib-dynamodb";
var cachedClient = null;
var cachedDocClient = null;
var cachedRegion = null;
function initializeDB(region) {
  if (cachedClient && cachedDocClient && cachedRegion === region) {
    return {
      DB_Client: cachedClient,
      db: cachedDocClient
    };
  }
  cachedRegion = region;
  cachedClient = new DynamoDBClient({ region });
  cachedDocClient = DynamoDBDocumentClient.from(cachedClient);
  return {
    DB_Client: cachedClient,
    db: cachedDocClient
  };
}
function clearDBCache() {
  cachedClient = null;
  cachedDocClient = null;
  cachedRegion = null;
}

// src/bootstrap/model.ts
var Model = class {
  constructor(name) {
    this.name = name;
  }
};

// src/bootstrap/router.ts
var NOT_FOUND_ERR = {
  statusCode: 404,
  body: JSON.stringify({ message: "API Not found" })
};
var NOT_FOUND = (message) => ({
  statusCode: 404,
  body: JSON.stringify({ message })
});
var METHOD_NOT_ALLOWED = (allowedMethods) => ({
  statusCode: 405,
  headers: { Allow: allowedMethods.join(", ") },
  body: JSON.stringify({ message: "Method not allowed" })
});
var Router = class {
  /**
   * Create a new Router instance.
   * 
   * @param event - API Gateway event
   * @param region - AWS region for DynamoDB
   * @param modules - Array of controller/service modules
   * @param options - Router configuration options
   * 
   * @example
   * ```typescript
   * const router = new Router(event, 'ap-southeast-2', modules, {
   *   basePath: '/api',
   *   debug: process.env.DEBUG === 'true',
   * });
   * ```
   */
  constructor(event, region, modules, options) {
    this.route = ``;
    this.routerName = "";
    this.controllers = [];
    this.debug = false;
    this.region = "";
    const opts = typeof options === "string" ? { basePath: options } : options ?? {};
    const pathname = event.path;
    const parentPath = opts.basePath ?? "";
    this.routerName = opts.basePath ?? "";
    this.debug = opts.debug ?? false;
    this.route = pathname.replace(parentPath, "").replace(/\/+$/, "");
    this.region = region;
    this.event = event;
    const { DB_Client, db } = initializeDB(region);
    this.DB_Client = DB_Client;
    this.db = db;
    this.initializeControllers(modules);
  }
  add(name, pathMap) {
    this.controllers = this.controllers.map((item) => {
      if (item.name == name) {
        const newItem = {
          ...item,
          pathMap: [...item.pathMap, pathMap]
        };
        return newItem;
      } else {
        return item;
      }
    });
  }
  async handle() {
    if (this.route == "") {
      const controller2 = this.controllers.find((c) => c.name == "default");
      if (!controller2) return NOT_FOUND("default controller");
      const method = this.event.httpMethod;
      const handlerFunc = controller2.pathMap.find(
        (item) => item.method == method
      );
      if (!!handlerFunc) {
        return handlerFunc.func(this.event);
      }
      if (controller2.pathMap.length > 0) {
        const allowedMethods = controller2.pathMap.map((item) => item.method);
        return METHOD_NOT_ALLOWED([...new Set(allowedMethods)]);
      }
      return NOT_FOUND("handler not found");
    }
    const pathArr = this.route?.split("/");
    pathArr.shift();
    if (this.debug) {
      console.log({ route: this.route, path: pathArr });
    }
    const controller = this.controllers.find(
      (item) => item.path == `/${pathArr[0]}`
    );
    if (!!controller && !!pathArr) {
      if (controller.pathMap?.length == 0) {
        return NOT_FOUND("controller");
      }
      let slug = void 0;
      const method = this.event.httpMethod;
      if (pathArr.length > 1) {
        pathArr.shift();
        slug = pathArr.join("/");
      }
      const handlerFunc = controller.pathMap.find(
        (item) => item.method == method && item.slug === slug
      ) ?? controller.pathMap.find(
        (item) => item.method == method && item.slug === void 0
      );
      if (!!handlerFunc) {
        return handlerFunc.func(this.event);
      }
      const availableHandlers = controller.pathMap.filter(
        (item) => item.slug === slug || item.slug === void 0
      );
      if (availableHandlers.length > 0) {
        const allowedMethods = availableHandlers.map((item) => item.method);
        return METHOD_NOT_ALLOWED([...new Set(allowedMethods)]);
      }
      return NOT_FOUND("handler not found");
    }
    return NOT_FOUND_ERR;
  }
  addController(props) {
    this.controllers.push(props);
  }
  /**
   * Initialize controllers with true constructor injection.
   * 
   * 1. Services are instantiated with (DB_Client, db) passed to constructor
   * 2. Controller is instantiated with services spread as constructor args
   * 3. Services are passed in the same order as defined in module.services[]
   */
  initializeControllers(modules) {
    if (this.debug) {
      console.log({ modules });
    }
    modules?.forEach((module) => {
      const services = module.services.map((ServiceClass) => {
        return new ServiceClass(this.DB_Client, this.db);
      });
      const controller = new module.controller(...services);
      const props = {
        name: controller.name,
        path: controller.path,
        pathMap: []
      };
      this.addController(props);
      controller.initializeRoutes(this);
    });
  }
};

// src/bootstrap/service.ts
var Service = class {
  constructor(name) {
    this.name = name;
  }
};

// src/bootstrap/dtos.ts
var ValidationError = class extends Error {
  constructor(message, issues) {
    super(message);
    this.name = "ValidationError";
    this.issues = issues;
  }
};
var DTO = class {
  constructor(schema) {
    this.schema = schema;
  }
  /**
   * Validate data using the provided Zod schema.
   * Throws a ValidationError if validation fails.
   */
  validate(data, error) {
    const parsed = this.schema.safeParse(data);
    if (!parsed.success) {
      const issues = parsed.error.issues.map((e) => ({
        item: e.path.join(".") || "(root)",
        message: e.message
      }));
      throw new ValidationError(error ?? `Validation failed`, issues);
    }
    return parsed.data;
  }
};

export {
  Controller,
  initializeDB,
  clearDBCache,
  Model,
  Router,
  Service,
  ValidationError,
  DTO
};
